STATS = '''<div class="stats"><div class="stat"><div class="stat-label">事项办理参考分</div><div class="stat-num">78<small> / 100</small></div><div class="stat-note">办理参考，不是官方信用评级</div><div class="score-line"><span></span></div></div><div class="stat"><div class="stat-label">在办失信事项</div><div class="stat-num">1<small> 件</small></div><div class="stat-note">累计 2 件，已修复 1 件</div></div><div class="stat"><div class="stat-label">同步异常渠道</div><div class="stat-num warning">2<small> 个</small></div><div class="stat-note">待核对第三方平台展示</div></div><div class="stat"><div class="stat-label">待办任务</div><div class="stat-num">2<small> 项</small></div><div class="stat-note">材料准备与同步核对</div></div></div>'''

def cases():
    return '''<section class="panel"><div class="panel-head"><div><h2>失信事项</h2><p>按事项管理，保留每一步办理记录</p></div><button class="plain-link" data-demo="事项筛选">全部 2 件</button></div><div class="case-list"><article class="case-item selected"><div><div class="case-top"><span>XF-2026-000455</span><span class="badge draft">草稿</span></div><h3>未按规定明码标价（建材价格公示不完整）</h3><div class="case-detail-meta">轻微失信 · 待核对整改证明</div></div><div class="case-stage"><div class="stage-text">办理进度 20%</div><div class="progress"><span style="width:20%"></span></div><button class="case-open" data-case="draft">查看事项</button></div></article><article class="case-item"><div><div class="case-top"><span>XF-2026-000437</span><span class="badge">已修复</span></div><h3>未按规定期限公示 2024 年度报告</h3><div class="case-detail-meta">轻微失信 · 官方修复后持续核对同步情况</div></div><div class="case-stage"><div class="stage-text">办理进度 100%</div><div class="progress"><span style="width:100%"></span></div><button class="case-open" data-case="repaired">查看事项</button></div></article></div></section>'''

QUICK = '<div class="quick-grid">'+''.join(f'<button class="quick" data-{attr}="{value}">{icon(i)}<span><strong>{title}</strong><small>{sub}</small></span></button>' for i,(attr,value,title,sub) in enumerate([('demo','智能诊断','智能诊断','确认办理路径'),('nav','notices','同步监测','核对展示状态'),('nav','progress','进度记录','查看流转节点'),('nav','knowledge','合规知识库','查阅法规与指引')]))+'</div>'
ACTIVITY = '''<section class="panel activity-panel"><div class="panel-head"><h2>最近动态</h2><span class="muted" style="font-size:12px">演示记录</span></div><div class="activity-list">'''+''.join(f'<div class="activity"><span class="event-dot"></span><div><time>11 月 2 日 · 21:22</time><p>保存{t}</p><small>版本 4 · 人工编辑</small></div></div>' for t in ['整改计划书草稿','材料目录与证明清单','授权委托书草稿'])+'</div></section>'
TASKS = '''<section class="panel task-panel"><div class="panel-head"><h2>接下来要做</h2><span class="badge draft">2 项待办</span></div><div class="task-row"><span class="task-symbol">○</span><div><p>补充整改证明材料</p><small>明码标价事项 · 材料准备</small></div></div><div class="task-row"><span class="task-symbol">○</span><div><p>核对第三方平台展示</p><small>年度报告事项 · 修复后监测</small></div></div></section>'''
JOURNEY = '''<section class="journey"><p class="eyebrow">当前办理 · XF-2026-000455</p><h2>未按规定明码标价</h2><p class="journey-note">草稿阶段：先核对整改事实，再确认适用的办理路径。</p><div class="journey-steps">'''+''.join(f'<div class="step {"current" if i == 0 else ""}">{s}</div>' for i,s in enumerate(['材料准备','提交官方','官方办理','修复归档','同步核对']))+'''</div><div class="journey-foot"><div><strong>办理进度 20%</strong><br><small>材料完备度与办理进度分别计算</small></div><button data-case="draft">继续准备材料</button></div></section>'''
DOSSIER = '''<section class="dossier"><div class="dossier-index"><h2>事项档案</h2><p>2 件事项，1 件在办</p><button class="active" data-dossier="draft">明码标价事项<br><span class="muted">草稿 · 20%</span></button><button data-dossier="repaired">年度报告事项<br><span class="muted">已修复 · 100%</span></button></div><div class="dossier-page"><div class="document-heading"><p class="eyebrow" id="dossier-id">XF-2026-000455</p><h2 id="dossier-title">未按规定明码标价</h2></div><dl class="facts"><dt>事项状态</dt><dd id="dossier-state"><span class="badge draft">草稿</span>　轻微失信</dd><dt>当前任务</dt><dd id="dossier-task">补充整改证明材料，核对材料目录。</dd><dt>办理进度</dt><dd id="dossier-progress">20% · 材料准备阶段</dd><dt>材料与记录</dt><dd>材料完备度独立展示；办理记录可追溯。</dd></dl><div class="related-docs"><span>整改情况说明</span><span>守信承诺书</span><span>材料目录</span></div><button class="primary" style="margin-top:24px" id="dossier-open" data-case="draft">打开事项档案</button></div></section>'''

KB = '''<section id="knowledge" class="hidden"><div class="heading"><div><p class="eyebrow">法规与办理参考</p><h1>合规知识库</h1><p class="module-intro">按地区查找法规底稿，先核对适用范围和官方来源。</p></div><button data-nav="dashboard">返回工作台</button></div><div class="knowledge-toolbar"><input id="kb-search" type="search" aria-label="搜索法规名称或地区" placeholder="搜索法规名称或地区，例如：湖南"><select id="kb-scope" aria-label="资料范围"><option value="core">企业信用相关</option><option value="all">全部压缩包资料</option></select><select id="kb-region" aria-label="地区"><option value="">全部地区</option><option>湖南</option><option>福建</option><option>陕西</option><option>内蒙古</option></select></div><div class="kb-layout"><section class="panel"><div class="panel-head"><h2>法规底稿</h2><span class="muted" id="kb-count"></span></div><div class="kb-list" id="kb-list"></div></section><aside class="panel kb-note"><h3>资料接入状态</h3><p>压缩包共 53 份文件。筛得 49 份企业信用相关候选、2 份背景资料、2 份其他主题文件。</p><p>这是设计预览中的本地资料目录。全部底稿尚待核对官方来源、有效版本和适用地区。</p><p>未复核资料不进入自动诊断，也不作为已审核政策发布。</p></aside></div></section>'''
OTHER = '''<section id="other" class="hidden"><div class="heading"><div><p class="eyebrow">功能导航预览</p><h1 id="other-title"></h1></div><button data-nav="dashboard">返回工作台</button></div><section class="panel"><h2>现有功能将在选定方向后沿用</h2><p class="module-intro">当前文件用于比较视觉与导航方式，不连接业务数据库。你可以切换企业工作台、浏览合规知识库，或从左上角菜单返回。</p></section></section>'''
NOTICE = '''<div class="notice"><span aria-hidden="true">ⓘ</span><p><strong>官方渠道办理，平台辅助准备。</strong> 本平台不代替行政机关受理申请；辅助数字凭证不替代官方修复证明。请以信用中国及作出决定机关的信息为准。</p></div>'''

JS = r'''
const docs=__DATA__;
const $=s=>document.querySelector(s);
function closeNav(){$('.sidebar').classList.remove('open');$('.overlay').classList.remove('visible');document.body.classList.remove('drawer-open');$('.menu-toggle').setAttribute('aria-expanded','false');}
$('.menu-toggle').onclick=()=>{$('.sidebar').classList.add('open');$('.overlay').classList.add('visible');document.body.classList.add('drawer-open');$('.menu-toggle').setAttribute('aria-expanded','true');};
$('.nav-close').onclick=closeNav;$('.overlay').onclick=closeNav;
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav()});
function navigate(key){['dashboard','knowledge','other'].forEach(id=>$('#'+id).classList.toggle('hidden',id!==(key==='dashboard'||key==='knowledge'?key:'other')));document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.nav===key));const names={dashboard:'企业工作台',knowledge:'合规知识库',notices:'同步监测',progress:'办理进度记录',collaboration:'协作与授权'};$('.crumb').textContent='企业服务 / '+names[key];$('#other-title').textContent=names[key];closeNav();window.scrollTo(0,0);if(key==='knowledge')renderKB();}
document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>navigate(el.dataset.nav));
function dialog(title,body){$('#dialog-title').textContent=title;$('#dialog-body').textContent=body;$('#detail').showModal();}
$('.dialog-close').onclick=()=>$('#detail').close();
document.querySelectorAll('[data-demo]').forEach(el=>el.onclick=()=>dialog(el.dataset.demo,'这是交互设计预览，当前不连接业务数据库。\n\n选定设计方向后，这里将继续使用平台已有的'+el.dataset.demo+'功能。'));
function openCase(key){const repaired=key==='repaired';dialog(repaired?'年度报告事项':'明码标价事项',(repaired?'XF-2026-000437\n状态：已修复\n办理进度：100%\n下一步：核对第三方平台展示。':'XF-2026-000455\n状态：草稿\n办理进度：20%\n下一步：补充整改证明材料。')+'\n\n演示数据。材料完备度需根据实际归档材料独立计算，不能由办理进度反推。\n辅助数字凭证不替代官方修复证明。');}
document.querySelectorAll('[data-case]').forEach(el=>el.onclick=()=>openCase(el.dataset.case));
document.querySelectorAll('[data-dossier]').forEach(el=>el.onclick=()=>{const done=el.dataset.dossier==='repaired';document.querySelectorAll('[data-dossier]').forEach(n=>n.classList.toggle('active',n===el));$('#dossier-id').textContent=done?'XF-2026-000437':'XF-2026-000455';$('#dossier-title').textContent=done?'未按规定期限公示 2024 年度报告':'未按规定明码标价';$('#dossier-state').textContent=done?'已修复 · 轻微失信':'草稿 · 轻微失信';$('#dossier-task').textContent=done?'核对第三方平台展示情况，留存同步记录。':'补充整改证明材料，核对材料目录。';$('#dossier-progress').textContent=done?'100% · 已修复':'20% · 材料准备阶段';$('#dossier-open').onclick=()=>openCase(el.dataset.dossier);});
function renderKB(){const q=$('#kb-search').value.trim(),region=$('#kb-region').value;const filtered=docs.filter(d=>(!q||(d.title+' '+(d.locality||'')).includes(q))&&(!region||d.title.includes(region))&&($('#kb-scope').value==='all'||d.applicability==='核心候选'));$('#kb-count').textContent=filtered.length+' 份候选';const list=$('#kb-list');list.replaceChildren();if(!filtered.length){const p=document.createElement('p');p.className='empty';p.textContent='没有匹配的底稿，试试其他地区或关键词。';list.append(p);}filtered.slice(0,10).forEach(d=>{const row=document.createElement('article');row.className='kb-row';const symbol=document.createElement('span');symbol.className='kb-symbol';symbol.textContent='文';const copy=document.createElement('div');copy.className='kb-copy';const title=document.createElement('h3');title.textContent=d.title;const meta=document.createElement('p');meta.textContent=(d.locality||'其他地区')+' · 待官方来源复核 · '+(d.extraction_status==='ok'?'已提取正文':'旧版 DOC 待转换');copy.append(title,meta);const button=document.createElement('button');button.textContent='查阅';button.onclick=()=>dialog(d.title,'待复核资料，不是已审核政策。\n\n'+(d.relevant_snippets.length?d.relevant_snippets.slice(0,3).join('\n\n'):'本份暂无已提取的信用修复条款，需进一步阅读完整原文。')+'\n\n正文施行日期线索（未核验）：\n'+(d.effective_date_clues.join('\n')||'待人工核对')+'\n\n官方链接、有效性和新旧版本关系尚未核对。');row.append(symbol,copy,button);list.append(row);});if(filtered.length>10){const more=document.createElement('p');more.className='muted';more.style.marginTop='18px';more.textContent='预览显示前 10 份；使用搜索缩小范围。';list.append(more);}}
['kb-search','kb-region','kb-scope'].forEach(id=>$('#'+id).addEventListener('input',renderKB));
window.addEventListener('resize',()=>{if(innerWidth>760)closeNav();});
'''.replace('__DATA__', json.dumps(documents, ensure_ascii=False).replace('</', '<\\/'))

directions = [
    (1,'澄明','专业工作台','Dieter Rams 的信息克制：把事项与下一步放在首位。'),
    (2,'同舟','深色协作侧栏','以书籍信息层级的思维整理复杂业务：突出任务分组。'),
    (3,'青岚','办理路径','企业导航与流程可视化参照：顶部导航、水平办理路径。'),
    (4,'矩阵','紧凑数据台','企业表格与工具面板参照：窄工具轨道、密集工作区域。'),
    (5,'墨序','法规档案','秒数轮盘：Warm Editorial，转化为清晰的企业档案阅读。'),
    (6,'经纬','法规索引','秒数轮盘：Japan Magazine Dense，转化为分栏目录式信息界面。'),
]

for mode,name,subtitle,reason in directions:
    if mode == 3:
        body = header()+STATS+'<div class="journey-layout">'+JOURNEY+TASKS+'</div><div class="columns"><div>'+cases()+QUICK+'</div>'+ACTIVITY+'</div>'
    elif mode == 5:
        body = header()+STATS+'<div class="edition-grid"><div>'+DOSSIER+'</div><aside class="edition-side"><h2>常用服务</h2>'+QUICK+ACTIVITY+'</aside></div>'
    elif mode == 6:
        body = header()+STATS+'<div class="columns"><div>'+cases()+QUICK+'</div><div>'+TASKS+ACTIVITY+'</div></div>'
    else:
        body = header()+STATS+'<div class="columns"><div>'+cases()+QUICK+'</div><aside>'+ACTIVITY+TASKS+'</aside></div>'
    page = f'''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>信复通 · {name}设计预览</title><style>{CSS}</style></head><body class="mode-{mode}"><div class="overlay"></div><aside class="sidebar" id="app-navigation" aria-label="主导航"><div class="brand"><div class="logo">{logo}</div><div><strong>信复通</strong><small>企业信用修复服务</small></div></div><button class="nav-close" aria-label="关闭导航">×</button><nav>{NAV}</nav><div class="nav-bottom"><strong>企业服务空间</strong>湖南恒基建材有限公司<br>视觉预览 · 演示数据</div></aside><div class="shell"><header class="topbar"><button class="menu-toggle" aria-label="展开导航" aria-controls="app-navigation" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M3 6h18M3 12h18M3 18h18"/></svg></button><div class="crumb">企业服务 / 企业工作台</div><div class="identity"><span class="preview-tag">{name} · {subtitle} · 设计预览</span><span class="avatar">周</span><span>周立恒</span><span class="role muted">企业负责人</span></div></header><main class="content"><section id="dashboard">{body}</section>{KB}{OTHER}{NOTICE}<footer class="footer"><span>信复通 · 企业信用修复辅助服务平台</span><span>视觉方案，不连接业务数据库</span></footer></main></div><dialog id="detail" aria-labelledby="dialog-title"><button class="dialog-close" aria-label="关闭详情">×</button><h2 id="dialog-title"></h2><div id="dialog-body" class="dialog-body"></div></dialog><script>{JS}</script></body></html>'''
    (ROOT / f'candidate-{mode}.html').write_text(page, encoding='utf-8')

# 六格先看结构，不替用户选定最终方向。
cards = ''.join(f'<article><div class="frame"><iframe title="{name}候选" src="candidate-{mode}.html" loading="eager"></iframe></div><div class="caption"><strong>{name} / {subtitle}</strong><p>{reason}</p></div></article>' for mode,name,subtitle,reason in directions)
(ROOT / 'six-directions.html').write_text('''<!doctype html><html lang="zh-CN"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>信复通 · 六个设计候选</title><style>*{box-sizing:border-box}body{margin:0;padding:32px;background:#e8edef;color:#183647;font:14px/1.6 "Noto Sans CJK SC","Microsoft YaHei",sans-serif}h1{font-size:25px;margin:0 0 4px}header>p{color:#566b78;margin:0 0 26px}section{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}article{background:white;border:1px solid #cbd6da;overflow:hidden}iframe{width:1440px;height:900px;border:0;transform:scale(.3);transform-origin:0 0;pointer-events:none}.frame{height:270px;overflow:hidden;background:white}.caption{padding:14px 18px;border-top:1px solid #dce2e3}.caption strong{font-size:16px}.caption p{margin:6px 0 0;color:#546976;font-size:13px}@media(max-width:900px){section{grid-template-columns:1fr}body{padding:20px}}</style><header><h1>信复通：六个方向，三种重点</h1><p>围绕同一组真实功能与演示数据探索；不是六套业务系统。</p></header><section>'''+cards+'</section></html>',encoding='utf-8')
print('已生成 6 个独立候选 HTML 与六格对照页。')
